-- Cloudflare D1 Migration 0010: indexed search table so Discover reads only matching rows.
-- One row per programme and subject. WITHOUT ROWID: the table is its own index (one write per row).
CREATE TABLE IF NOT EXISTS program_search (
    country_code TEXT NOT NULL,
    subject TEXT NOT NULL,
    level TEXT NOT NULL,
    rank_sort INTEGER NOT NULL,
    program_id TEXT NOT NULL,
    university_id TEXT NOT NULL,
    tuition REAL,
    PRIMARY KEY (country_code, subject, level, rank_sort, program_id)
) WITHOUT ROWID;

INSERT OR IGNORE INTO program_search (country_code, subject, level, rank_sort, program_id, university_id, tuition) SELECT u.country_code, 'Computer Science', p.level, COALESCE(u.ranking, 100000), p.id, p.university_id, p.tuition FROM programs p JOIN universities u ON u.id = p.university_id WHERE p.removed_at IS NULL AND u.country_code IS NOT NULL AND (', ' || p.subject_category || ', ') LIKE '%, Computer Science, %';
INSERT OR IGNORE INTO program_search (country_code, subject, level, rank_sort, program_id, university_id, tuition) SELECT u.country_code, 'Artificial Intelligence', p.level, COALESCE(u.ranking, 100000), p.id, p.university_id, p.tuition FROM programs p JOIN universities u ON u.id = p.university_id WHERE p.removed_at IS NULL AND u.country_code IS NOT NULL AND (', ' || p.subject_category || ', ') LIKE '%, Artificial Intelligence, %';
