DROP INDEX IF EXISTS idx_prog_subject;
DROP INDEX IF EXISTS idx_prog_level;

ALTER TABLE crawl_countries ADD COLUMN institutions_checked INTEGER DEFAULT 0;
ALTER TABLE crawl_countries ADD COLUMN institutions_with_programs INTEGER DEFAULT 0;
ALTER TABLE crawl_countries ADD COLUMN last_update TIMESTAMP;
UPDATE crawl_countries SET
    institutions_checked = (SELECT COUNT(*) FROM institution_queue q WHERE q.country_code = crawl_countries.country_code AND q.last_crawled_at IS NOT NULL),
    institutions_with_programs = (SELECT COUNT(*) FROM institution_queue q WHERE q.country_code = crawl_countries.country_code AND q.programs_found > 0),
    last_update = (SELECT MAX(last_crawled_at) FROM institution_queue q WHERE q.country_code = crawl_countries.country_code);

CREATE INDEX IF NOT EXISTS idx_iq_pending ON institution_queue(students DESC) WHERE status = 'pending';
